// Le topic est de la forme: iot/{did}/operational/request
// msg.payload contient le corps JSON envoyé par le dispositif
const topicParts = msg.topic.split('/');
const didFromTopic = topicParts[1];

let body;
try {
    body = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    node.warn('Payload JSON invalide: ' + msg.payload);
    return null;
}

msg.did = didFromTopic;
msg.jwt = body.jwt;
msg.timestamp = body.timestamp;
msg.proofSignature = body.proofSignature;
msg.requestedPermission = body.requestedPermission || null;

// Clé Redis attendue par le cache HIT
msg.redisKey = 'device:' + didFromTopic;

return msg;

const redis = new Redis({
    host: 'host.docker.internal',
    port: 6379
});

const data = await redis.hgetall(msg.redisKey);
redis.disconnect();

msg.cache = data;
msg.cacheHit = data && Object.keys(data).length > 0;

return msg;

msg.payload = {
    did: msg.did,
    jwt: msg.jwt,
    timestamp: msg.timestamp,
    proofSignature: msg.proofSignature,
    requestedPermission: msg.requestedPermission
};

msg.headers = { 'Content-Type': 'application/json' };

return msg;

msg.topic = 'iot/' + msg.did + '/operational/response';
msg.payload = msg.payload; // déjà la réponse JSON du backend (authorized, status, permissions, reason)

return msg;

function base32Decode(str) {
    const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
    let bits = 0, value = 0;
    const output = [];
    for (const char of str.toUpperCase()) {
        const idx = alphabet.indexOf(char);
        if (idx === -1) continue;
        value = (value << 5) | idx;
        bits += 5;
        if (bits >= 8) {
            output.push((value >>> (bits - 8)) & 0xFF);
            bits -= 8;
        }
    }
    return Buffer.from(output);
}

function base64UrlDecode(str) {
    let s = str.replace(/-/g, '+').replace(/_/g, '/');
    while (s.length % 4) s += '=';
    return Buffer.from(s, 'base64');
}

function decodeJwtPayload(jwt) {
    const parts = jwt.split('.');
    if (parts.length !== 3) throw new Error('Format JWT invalide');
    const json = base64UrlDecode(parts[1]).toString('utf8');
    return JSON.parse(json);
}

function verifyJwtSignature(jwt, issuerPublicKeyBase32) {
    const parts = jwt.split('.');
    if (parts.length !== 3 || !issuerPublicKeyBase32) return false;
    const signingInput = Buffer.from(parts[0] + '.' + parts[1], 'utf8');
    const signature = base64UrlDecode(parts[2]);
    const issuerPublicKey = base32Decode(issuerPublicKeyBase32);
    return nacl.sign.detached.verify(signingInput, signature, issuerPublicKey);
}

function base64Decode(str) {
    return Buffer.from(str, 'base64');
}

function sameBytes(a, b) {
    return a.length === b.length && a.every((value, index) => value === b[index]);
}

function buildLogMsg(did, authorized, reason, requestedPermission) {
    return {
        payload: { did, authorized, reason: reason || null, requestedPermission: requestedPermission || null },
        headers: {
            'Content-Type': 'application/json',
            'X-Gateway-Secret': env.get('GATEWAY_SHARED_SECRET') || ''
        }
    };
}

try {
    msg.topic = 'iot/' + msg.did + '/operational/response';

    const cache = msg.cache;
    const publicKeyBytes = base32Decode(cache.publicKey);

    if (!verifyJwtSignature(msg.jwt, cache.issuerPublicKey)) {
        msg.payload = { authorized: false, reason: 'Signature JWT PoP invalide (cache)' };
        return [null, msg, buildLogMsg(msg.did, false, 'Signature JWT PoP invalide (cache)', msg.requestedPermission)];
    }

    const claims = decodeJwtPayload(msg.jwt);

    if (claims.sub !== msg.did) {
        msg.payload = { authorized: false, reason: 'DID incoherent entre topic MQTT et JWT (cache)' };
        return [null, msg, buildLogMsg(msg.did, false, 'DID incoherent entre topic MQTT et JWT (cache)', msg.requestedPermission)];
    }

    if (cache.issuerDid && claims.iss !== cache.issuerDid) {
        msg.payload = { authorized: false, reason: 'Issuer JWT inattendu (cache)' };
        return [null, msg, buildLogMsg(msg.did, false, 'Issuer JWT inattendu (cache)', msg.requestedPermission)];
    }

    const cnfKey = claims.cnf && claims.cnf.jwk && claims.cnf.jwk.x;
    if (!cnfKey || !sameBytes(base64Decode(cnfKey), publicKeyBytes)) {
        msg.payload = { authorized: false, reason: 'JWT PoP non lie a la cle du dispositif (cache)' };
        return [null, msg, buildLogMsg(msg.did, false, 'JWT PoP non lie a la cle du dispositif (cache)', msg.requestedPermission)];
    }

    const now = Math.floor(Date.now() / 1000);
    if (claims.exp < now) {
        msg.payload = { authorized: false, reason: 'JWT PoP expire (cache)' };
        return [null, msg, buildLogMsg(msg.did, false, 'JWT PoP expire (cache)', msg.requestedPermission)];
    }

    if (Math.abs(now - msg.timestamp) > 30) {
        msg.payload = { authorized: false, reason: 'Preuve de possession non fraiche (cache)' };
        return [null, msg, buildLogMsg(msg.did, false, 'Preuve de possession non fraiche (cache)', msg.requestedPermission)];
    }

    const proofMessage = claims.jti + ':' + msg.timestamp;
    const messageBytes = Buffer.from(proofMessage, 'utf8');
    const signatureBytes = base64UrlDecode(msg.proofSignature);

    const isValid = nacl.sign.detached.verify(messageBytes, signatureBytes, publicKeyBytes);

    if (!isValid) {
        msg.payload = { authorized: false, reason: 'Preuve de possession invalide (cache)' };
        return [null, msg, buildLogMsg(msg.did, false, 'Preuve de possession invalide (cache)', msg.requestedPermission)];
    }

    const permissions = (cache.permissions || '').split(',').filter(p => p.length > 0);

    if (msg.requestedPermission && !permissions.includes(msg.requestedPermission)) {
        const reason = 'Permission non accordee : ' + msg.requestedPermission;
        msg.payload = { authorized: false, reason };
        const logMsg = buildLogMsg(msg.did, false, reason, msg.requestedPermission);
        logMsg.payload.violationType = 'PERMISSION_VIOLATION';
        return [null, msg, logMsg];
    }

    msg.payload = {
        authorized: true,
        did: msg.did,
        status: cache.status,
        permissions: permissions
    };
    return [msg, null, buildLogMsg(msg.did, true, null, msg.requestedPermission)];

} catch (e) {
    msg.topic = 'iot/' + msg.did + '/operational/response';
    const reason = 'Erreur de verification locale : ' + e.message;
    msg.payload = { authorized: false, reason };
    return [null, msg, buildLogMsg(msg.did, false, reason, msg.requestedPermission)];
}
